create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,handle text unique,country text,avatar_url text,role text not null default 'buyer',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shops(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),name text not null,slug text not null unique,description text default '',is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,name text not null,slug text not null,description text default '',price numeric(20,2) not null check(price>=0),currency char(3) not null default 'USD',image_url text,is_active boolean not null default true,created_at timestamptz not null default now(),unique(shop_id,slug));
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.profiles(id),shop_id uuid not null references public.shops(id),status text not null default 'pending',currency char(3) not null,subtotal numeric(20,2) not null,created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid not null references public.products(id),quantity integer not null check(quantity>0),unit_price numeric(20,2) not null);
create table if not exists public.payment_events(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id),provider text not null,provider_event_id text not null unique,payload jsonb not null,created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1))) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security; alter table public.shops enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create policy profiles_self on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy shops_public_read on public.shops for select using(is_active=true);
create policy shops_owner_write on public.shops for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy products_public_read on public.products for select using(is_active=true);
create policy products_owner_write on public.products for all using(exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=auth.uid()));
create policy orders_buyer_read on public.orders for select using(auth.uid()=buyer_id);
create policy order_items_buyer_read on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and o.buyer_id=auth.uid()));
